'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={demo:true,recording:false,started:0,session:null,window:30,view:'live',wake:null};
const bands={chest:{samples:[],device:null,last:0,missing:0,total:0,baseline:null},abdomen:{samples:[],device:null,last:0,missing:0,total:0,baseline:null}};
let history=[];try{history=JSON.parse(localStorage.getItem('somna.sessions')||'[]')}catch{};
let settings={service:'b37a0001-9c4b-4f53-a3c1-5d8e64010000',characteristic:'b37a0002-9c4b-4f53-a3c1-5d8e64010000'};try{Object.assign(settings,JSON.parse(localStorage.getItem('somna.settings')||'{}'))}catch{}
$('#service-uuid').value=settings.service;$('#characteristic-uuid').value=settings.characteristic;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function modal(title,body){$('#modal-content').replaceChildren();const h=document.createElement('h2');h.textContent=title;$('#modal-content').append(h);body.forEach(t=>{const p=document.createElement('p');p.textContent=t;$('#modal-content').append(p)});$('#modal').showModal()}
$('.modal-close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};
function view(v){state.view=v;$$('.view').forEach(e=>e.classList.toggle('hidden',e.id!==v));$$('.nav').forEach(e=>e.classList.toggle('active',e.dataset.view===v));$('#crumb').textContent={live:'Overview',history:'Session history',devices:'Devices & setup'}[v];if(v==='history')renderHistory();if(v==='devices')updateDevices();if(v==='live')draw();}
$$('.nav').forEach(b=>b.onclick=()=>view(b.dataset.view));$('#manage').onclick=$('#mode-toggle').onclick=()=>view('devices');
$('#help').onclick=$('#learn').onclick=()=>modal('Understanding your measurements',['Somna displays respiratory band movement from two independent wireless nodes. Demo mode generates artificial signals and all demo recordings remain labeled.','Breathing rate is estimated from chest movement cycles. Relative movement compares the recent peak-to-peak chest signal with a baseline; it is not lung volume or respiratory strength.','Signal coverage estimates received samples from a configured 20 Hz stream and sequence gaps. It does not prove that a band is fitted correctly or that a signal is clinically usable.','Recordings stay in this browser. Export sessions for backup. This prototype cannot establish time asleep, sleep stages, oxygen levels, or diagnose apnea. Browser collection can stop when the device sleeps or the page closes.']);
$('#window').onchange=e=>{state.window=Number(e.target.value);updateAxis()};function updateAxis(){$$('.time-axis span').forEach((e,i)=>e.textContent=i===3?'Now':'−'+Math.round(state.window*(1-i/3))+'s')}
function duration(ms){let s=Math.floor(ms/1000);return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(x=>String(x).padStart(2,'0')).join(':')}
function addSample(name,s){const b=bands[name];b.last=s.received;b.total++;b.samples.push(s);if(b.samples.length>2400)b.samples.shift();if(state.recording)state.session.samples.push({...s,band:name});}
const epoch=Date.now();let demoSeq=0;function sim(t,n){const phase=n==='chest'?0:.28;const amplitude=n==='chest'?1:.8;return amplitude*(Math.sin(t*Math.PI*.5+phase)+.10*Math.sin(t*Math.PI+phase))*(.95+.08*Math.sin(t/19))+.015*Math.sin(t*21)}
for(let i=-1200;i<=0;i++){const received=epoch+i*50;for(const n of Object.keys(bands))addSample(n,{received,t:i*50,seq:i,value:sim(i*.05,n)})}
function setDemo(on){if(state.recording){toast('Stop the recording before changing data source.');$('#demo-check').checked=state.demo;return}state.demo=on;$('#demo-check').checked=on;for(const b of Object.values(bands)){b.samples=[];b.baseline=null;b.total=0;b.missing=0;b.seq=undefined;b.last=0;if(on&&b.device?.gatt.connected)b.device.gatt.disconnect()};$('#mode-label').textContent=on?'Demo mode':'Hardware mode';$('#mode-copy').textContent=on?' · Explore simulated chest and abdomen signals.':' · Connect both bands before recording.';$('#sample-label').textContent=on?'20 samples / second · simulated':'20 Hz target · receive-time alignment';$('#rate-note').textContent=on?'Simulated rhythm':'Estimated from chest cycles';updateDevices();draw()}
$('#demo-check').onchange=e=>setDemo(e.target.checked);
function recent(name,seconds=20){const a=bands[name].samples;const now=Date.now();return a.filter(s=>s.received>now-seconds*1000)}
function range(a){if(!a.length)return 0;let min=Infinity,max=-Infinity;for(const s of a){min=Math.min(min,s.value);max=Math.max(max,s.value)}return max-min}
function rate(a){if(a.length<100)return null;const vals=a.map(s=>s.value),mean=vals.reduce((s,x)=>s+x,0)/vals.length,span=range(a);if(span<1e-12)return null;const peaks=[];let armed=false;for(let i=0;i<a.length;i++){if(vals[i]<mean-span*.12)armed=true;if(armed&&vals[i]>mean+span*.12){if(!peaks.length||a[i].received-peaks.at(-1)>1000)peaks.push(a[i].received);armed=false}}if(peaks.length<3)return null;const intervals=peaks.slice(1).map((t,i)=>t-peaks[i]).sort((a,b)=>a-b);return 60000/intervals[Math.floor(intervals.length/2)]}
function connected(n){return state.demo||!!bands[n].device?.gatt.connected}
function fresh(n){return connected(n)&&Date.now()-bands[n].last<2000}
function metrics(){const a=recent('chest'),r= fresh('chest')?rate(a):null;$('#rate').textContent=r?r.toFixed(1):'—';const b=bands.chest;if(!b.baseline&&a.length>=100)b.baseline={center:a.reduce((s,x)=>s+x.value,0)/a.length,span:range(a)||1};const amplitude=fresh('chest')&&b.baseline?Math.round(range(recent('chest',8))/b.baseline.span*100):null;$('#amplitude').textContent=amplitude??'—';$('.amplitude-track i').style.width=Math.min(100,(amplitude||0)/1.6)+'%';let actual=0,expected=0;for(const n of Object.keys(bands)){const a=recent(n,10);actual+=a.length;expected+=200}const coverage=Math.min(100,Math.round(actual/expected*100));$('#coverage').textContent=state.demo?100:coverage;$('#coverage-note').textContent=state.demo?'Both simulated channels available':Object.keys(bands).every(fresh)?'Both channels receiving':'Waiting for both band signals';if(state.recording){$('#elapsed').textContent=duration(Date.now()-state.started);$('#timeline-description').textContent='Current recording · select a point to inspect.'}updateDevices(false)}
$('#calibrate').onclick=()=>{if(state.recording)return toast('Set the baseline before starting a recording.');let count=0;for(const n of Object.keys(bands)){const a=recent(n,10);if(a.length>=100&&fresh(n)){bands[n].baseline={center:a.reduce((s,x)=>s+x.value,0)/a.length,span:range(a)||1};count++}}toast(count===2?'Baseline set for both bands.':count?'One band calibrated. Wait for the other signal.':'Collect at least 5 seconds of signal first.')};
async function toggleRecording(){if(state.recording){state.recording=false;updateDevices();const s=state.session;s.ended=Date.now();s.baselines=Object.fromEntries(Object.entries(bands).map(([n,b])=>[n,b.baseline]));history.unshift(s);try{localStorage.setItem('somna.sessions',JSON.stringify(history))}catch{toast('Browser storage is full. Export this session now to keep it.')}$('#record').textContent='● Start recording';$('#session-status').textContent='Session saved';$('#record-dot').classList.remove('recording');$('#timeline-tag').textContent=s.demo?'DEMO RECORDING':'RECORDED SESSION';state.wake?.release();toast('Session saved. Review it in Session history.');return}if(!state.demo&&!Object.keys(bands).every(fresh))return toast('Connect both bands and wait for incoming samples first.');state.started=Date.now();state.session={id:crypto.randomUUID(),started:state.started,ended:null,demo:state.demo,samples:[],notes:''};state.recording=true;updateDevices();$('#record').textContent='■ Stop & save';$('#session-status').textContent='Recording '+(state.demo?'demo':'bands');$('#record-dot').classList.add('recording');$('#timeline-tag').textContent=state.demo?'DEMO RECORDING':'RECORDING';try{state.wake=await navigator.wakeLock?.request('screen')}catch{}toast('Recording started. Keep this page open and the device awake.')}
$('#record').onclick=toggleRecording;
function canvas(id){const c=$(id),rect=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;if(!rect.width)return null;if(c.width!==Math.round(rect.width*dpr)||c.height!==Math.round(rect.height*dpr)){c.width=rect.width*dpr;c.height=rect.height*dpr}const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,rect.width,rect.height);return{ctx,w:rect.width,h:rect.height}}
function grid(ctx,w,h){ctx.lineWidth=1;ctx.strokeStyle='#2a383b';ctx.setLineDash([2,5]);for(let y=0;y<=4;y++){ctx.beginPath();ctx.moveTo(0,y*h/4);ctx.lineTo(w,y*h/4);ctx.stroke()}for(let x=0;x<=10;x++){ctx.beginPath();ctx.moveTo(x*w/10,0);ctx.lineTo(x*w/10,h);ctx.stroke()}ctx.setLineDash([])}
function plot(name){const v=canvas('#'+name+'-chart');if(!v)return;const{ctx,w,h}=v;grid(ctx,w,h);const b=bands[name],a=recent(name,state.window),now=Date.now(),baseline=b.baseline;const span=baseline?.span||range(a)||2,center=baseline?.center??(a.length?a.reduce((s,x)=>s+x.value,0)/a.length:0);ctx.strokeStyle=name==='chest'?'#94b8ed':'#79cdb9';ctx.lineWidth=1.8;ctx.beginPath();let prev=null;for(const s of a){const x=w*(1-(now-s.received)/(state.window*1000)),y=h/2-(s.value-center)/span*h*.68;if(!prev||s.received-prev.received>400)ctx.moveTo(x,y);else ctx.lineTo(x,y);prev=s}ctx.stroke();if(!a.length){ctx.fillStyle='#81958d';ctx.font='12px sans-serif';ctx.fillText('Waiting for band signal…',20,h/2)}}
function timelineData(){const s=state.session;if(s?.samples.length){const len=s.samples.length,points=[];for(let i=0;i<len;i+=Math.max(1,Math.floor(len/250))){const p=s.samples[i];if(p.band==='chest')points.push({t:p.received,v:p.value})}return{points,start:s.started,end:s.ended||Date.now(),raw:true}}return{points:Array.from({length:240},(_,i)=>({t:i,v:15+1.4*Math.sin(i*.07)+.6*Math.sin(i*.32)+(i>130&&i<147?-2:0)})),start:0,end:239,raw:false}}
function drawTimeline(){const v=canvas('#timeline');if(!v)return;const{ctx,w,h}=v;grid(ctx,w,h);const d=timelineData();let min=Math.min(...d.points.map(p=>p.v)),max=Math.max(...d.points.map(p=>p.v));const span=max-min||1;ctx.beginPath();d.points.forEach((p,i)=>{const x=(p.t-d.start)/(d.end-d.start||1)*w,y=h*.85-(p.v-min)/span*h*.65;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle='#94b8ed';ctx.lineWidth=1.4;ctx.stroke();if(d.points.length){ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();const grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#94b8ed20');grad.addColorStop(1,'#94b8ed00');ctx.fillStyle=grad;ctx.fill()}if(d.raw){$('#timeline-start').textContent=new Date(d.start).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('#timeline-mid').textContent=duration((d.end-d.start)/2);$('#timeline-end').textContent=duration(d.end-d.start);$('.timeline-bottom>span:first-child').textContent='Chest movement · recorded samples'}}
$('#timeline').onclick=e=>{inspectAt(e.offsetX/e.currentTarget.clientWidth);const d=timelineData(),f=Math.max(0,Math.min(1,e.offsetX/e.currentTarget.clientWidth));$('#timeline-selection').textContent=d.raw?'Selected '+duration(f*(d.end-d.start))+' into recording':'Example: '+new Date(2026,0,1,23,Math.round(f*480)).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+' · '+d.points[Math.round(f*239)].v.toFixed(1)+' breaths/min'};
function draw(){if(state.view!=='live')return;plot('chest');plot('abdomen');drawTimeline()}window.addEventListener('resize',draw);
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(s){if(!s?.samples.length)return toast('Record a session first to export its samples.');const rows=['source,band,received_iso,device_time_ms,sequence,raw_value',...s.samples.map(p=>[s.demo?'simulated':'hardware',p.band,new Date(p.received).toISOString(),p.t,p.seq,p.value].join(','))];download(rows.join('\n'),'somna-'+new Date(s.started).toISOString().slice(0,19).replaceAll(':','-')+'.csv','text/csv')}
$('#export').onclick=()=>exportCSV(state.session||history[0]);
function renderHistory(){const list=$('#history-list');list.replaceChildren();if(!history.length){const e=document.createElement('article');e.className='panel empty';e.innerHTML='<h2>Your first session starts here.</h2><p>Record a demo or connect your bands, then return to review your recording.</p><button class="primary">Go to overview ↗</button>';e.querySelector('button').onclick=()=>view('live');list.append(e);return}for(const s of history){const el=document.createElement('article');el.className='panel history-item';const div=document.createElement('div'),h=document.createElement('h2'),p=document.createElement('p');h.textContent=new Date(s.started).toLocaleString([],{dateStyle:'medium',timeStyle:'short'});p.textContent=(s.demo?'Simulated recording':'Hardware recording')+' · '+duration(s.ended-s.started)+' · '+s.samples.length.toLocaleString()+' samples';div.append(h,p);const b=document.createElement('button');b.className='secondary';b.textContent='Review session ↗';b.onclick=()=>review(s);el.append(div,b);list.append(el)}}
function review(s){if(state.recording)return toast('Stop recording before reviewing another session.');const el=$('#history-detail');el.classList.remove('hidden');el.replaceChildren();const h=document.createElement('h2');h.textContent='Session review';const p=document.createElement('p');const counts={chest:0,abdomen:0};s.samples.forEach(x=>counts[x.band]++);p.textContent=(s.demo?'DEMO · ':'')+duration(s.ended-s.started)+' recording · Chest: '+counts.chest+' samples · Abdomen: '+counts.abdomen+' samples';el.append(h,p);const note=document.createElement('p');note.textContent='Select “View timeline” to inspect the recording in the overview. Raw data is preserved in both export formats.';el.append(note);for(const[label,fn]of [['View timeline',()=>{state.session=s;$('#timeline-tag').textContent=s.demo?'DEMO RECORDING':'RECORDED SESSION';$('#timeline-description').textContent='Saved recording · chest movement over the session.';view('live')}],['Export CSV',()=>exportCSV(s)],['Backup JSON',()=>download(JSON.stringify(s),'somna-session-'+s.id+'.json','application/json')]]){const b=document.createElement('button');b.textContent=label;b.className='secondary';b.onclick=fn;el.append(b)}el.scrollIntoView({behavior:'smooth',block:'nearest'})}
$('#import-btn').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const s=JSON.parse(await file.text());if(typeof s.id!=='string'||!Number.isFinite(s.started)||!Number.isFinite(s.ended)||s.ended<s.started||typeof s.demo!=='boolean'||!Array.isArray(s.samples)||!s.samples.every(p=>['chest','abdomen'].includes(p.band)&&['received','t','seq','value'].every(k=>Number.isFinite(p[k]))))throw Error('Invalid session format');if(history.some(x=>x.id===s.id))return toast('This session is already saved.');history.unshift(s);try{localStorage.setItem('somna.sessions',JSON.stringify(history))}catch{toast('Imported for this visit; storage is full. Export a backup.')}renderHistory();toast('Session imported.')}catch(err){toast('Could not import: '+err.message)}e.target.value=''};
function updateDevices(render=true){for(const n of Object.keys(bands)){const label=state.demo?'SIMULATED':fresh(n)?'RECEIVING':connected(n)?'NO RECENT DATA':'DISCONNECTED';$('#'+n+'-state').textContent=label;$('#'+n+'-connected').textContent=state.demo?'Demo signal':fresh(n)?'Receiving':connected(n)?'No recent data':'Disconnected'}if(!render)return;$('#device-cards').replaceChildren();for(const n of Object.keys(bands)){const el=document.createElement('article');el.className='panel device-card';const h=document.createElement('h2');h.textContent=(n==='chest'?'Chest':'Abdomen')+' band';const p=document.createElement('p');p.textContent=state.demo?'Simulated signal active. Switch off demo mode to connect your device.':connected(n)?'Connected. Watch the live graph to verify incoming samples.':'RIP band → LDC1612 → XIAO ESP32C3';const b=document.createElement('button');b.className='primary';b.textContent=connected(n)&&!state.demo?'Disconnect':'Connect '+n;b.disabled=state.demo||!navigator.bluetooth||state.recording;b.onclick=()=>{if(bands[n].device?.gatt.connected)bands[n].device.gatt.disconnect();else connect(n)};el.append(h,p,b);$('#device-cards').append(el)}}
$('#bluetooth-support').textContent=navigator.bluetooth?'Web Bluetooth is available. Pair each band separately; keep this page open during recording.':'This browser does not expose Web Bluetooth. Demo and session review work here. Use a supported Chrome desktop or Android browser for direct band connections.';
async function connect(n){try{const device=await navigator.bluetooth.requestDevice({filters:[{services:[settings.service]}]});const other=n==='chest'?'abdomen':'chest';if(bands[other].device?.id===device.id)throw Error('This node is assigned to the other band. Choose the second device.');const server=await device.gatt.connect();const service=await server.getPrimaryService(settings.service);const characteristic=await service.getCharacteristic(settings.characteristic);bands[n].device=device;bands[n].seq=undefined;bands[n].offset=undefined;bands[n].samples=[];device.addEventListener('gattserverdisconnected',()=>{updateDevices();toast(n+' band disconnected. The recording will preserve this data gap.')});characteristic.addEventListener('characteristicvaluechanged',e=>{try{const p=JSON.parse(new TextDecoder().decode(e.target.value));if(!['t','seq','value'].every(k=>Number.isFinite(p[k])))throw Error('Invalid sample');const b=bands[n];if(b.seq!==undefined&&p.seq<=b.seq)return;if(b.seq!==undefined)b.missing+=Math.max(0,p.seq-b.seq-1);b.seq=p.seq;const arrival=Date.now();b.offset??=arrival-p.t;addSample(n,{...p,received:b.offset+p.t});}catch{toast('Unreadable sample. Expected JSON: t, seq, value.')}});await characteristic.startNotifications();updateDevices();toast(n+' band connected. Waiting for samples.')}catch(e){toast(e.name==='NotFoundError'?'Pairing cancelled or no matching device found.':e.message)}}
$('#save-settings').onclick=()=>{const re=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;const service=$('#service-uuid').value.trim(),characteristic=$('#characteristic-uuid').value.trim();if(!re.test(service)||!re.test(characteristic))return toast('Enter valid 128-bit UUIDs.');if(state.recording)return toast('Stop recording before changing settings.');settings={service,characteristic};localStorage.setItem('somna.settings',JSON.stringify(settings));toast('Settings saved. Reconnect bands to use them.')};
window.addEventListener('beforeunload',e=>{if(state.recording){e.preventDefault();e.returnValue=''}});
setInterval(()=>{if(state.demo){const now=Date.now(),t=(now-epoch)/1000;demoSeq++;for(const n of Object.keys(bands))addSample(n,{received:now,t:Math.round(t*1000),seq:demoSeq,value:sim(t,n)})}},50);setInterval(()=>{metrics();draw()},200);updateDevices();metrics();draw();

function inspectAt(f){const session=state.session;if(!session?.samples.length)return;f=Math.max(0,Math.min(1,f));const end=session.ended||Date.now(),center=session.started+f*(end-session.started),start=Math.max(session.started,center-15000),stop=Math.min(end,start+30000);$('#inspector').classList.remove('hidden');$('#inspector-label').textContent=duration(start-session.started)+' – '+duration(stop-session.started)+' into recording · gaps preserved';for(const n of Object.keys(bands)){const v=canvas('#inspect-'+n);if(!v)continue;const{ctx,w,h}=v;grid(ctx,w,h);const a=session.samples.filter(p=>p.band===n&&p.received>=start&&p.received<=stop);const base=session.baselines?.[n],span=base?.span||range(a)||1,mid=base?.center??(a.length?a.reduce((s,p)=>s+p.value,0)/a.length:0);ctx.strokeStyle=n==='chest'?'#94b8ed':'#79cdb9';ctx.lineWidth=1.6;ctx.beginPath();let last=null;for(const p of a){const x=(p.received-start)/(stop-start||1)*w,y=h/2-(p.value-mid)/span*h*.68;if(!last||p.received-last.received>400)ctx.moveTo(x,y);else ctx.lineTo(x,y);last=p}ctx.stroke()}$('#inspector').scrollIntoView({behavior:'smooth',block:'nearest'})}
$('#close-inspector').onclick=()=>$('#inspector').classList.add('hidden');
